<div class="page-actions"><div><p class="muted">Ringkasan stok, pembelian, dan penjualan Gudang Kita.</p></div></div>
<div class="report-grid"><div class="card"><div class="card-header"><h2>Ringkasan Stok</h2></div><div class="table-wrap"><table><thead><tr><th>Kode</th><th>Produk</th><th>Gudang</th><th>Stok</th><th>Minimum</th></tr></thead><tbody><?php foreach($stock as $r):?><tr><td><?=e($r['code'])?></td><td><?=e($r['name'])?></td><td><?=e($r['warehouse_name'])?></td><td><?=number_format((float)$r['current_stock'],2,',','.')?></td><td><?=number_format((float)$r['minimum_stock'],2,',','.')?></td></tr><?php endforeach;?></tbody></table></div></div>
<div class="card"><div class="card-header"><h2>Purchase per Bulan</h2></div><div class="table-wrap"><table><thead><tr><th>Periode</th><th>Order</th><th>Total</th></tr></thead><tbody><?php foreach($purchase as $r):?><tr><td><?=e($r['period'])?></td><td><?=e($r['orders'])?></td><td>Rp <?=number_format((float)$r['total'],0,',','.')?></td></tr><?php endforeach;?><?php if(!$purchase):?><tr><td colspan="3" class="empty">Belum ada transaksi received.</td></tr><?php endif;?></tbody></table></div></div>
<div class="card"><div class="card-header"><h2>Sales per Bulan</h2></div><div class="table-wrap"><table><thead><tr><th>Periode</th><th>Order</th><th>Total</th></tr></thead><tbody><?php foreach($sales as $r):?><tr><td><?=e($r['period'])?></td><td><?=e($r['orders'])?></td><td>Rp <?=number_format((float)$r['total'],0,',','.')?></td></tr><?php endforeach;?><?php if(!$sales):?><tr><td colspan="3" class="empty">Belum ada transaksi completed.</td></tr><?php endif;?></tbody></table></div></div></div>
